# === END EMBEDDED OFF LIBRARY ===


def build_catalog():
    """Catalog the embedded OFF models, with fissaries at the end."""
    if not EMBEDDED_OFF:
        sys.exit(
            "noble: no embedded OFF files yet. Run build_noble_embedded.py "
            "with Connor's library folder first."
        )
    catalog = [(symbol, relative) for symbol, (relative, _, _) in EMBEDDED_OFF.items()]
    normal = [(s, r) for s, r in catalog if s not in FISSARIES]
    normal.sort(key=lambda item: natural_key(item[1]))
    fissary = {s: r for s, r in catalog if s in FISSARIES}
    if len(normal) != 146 or set(fissary) != set(FISSARIES):
        sys.exit("noble: the embedded catalog is incomplete (expected 146 + 2 fissaries)")
    return normal + [(s, fissary[s]) for s in FISSARIES]


def list_catalog(catalog):
    """List Connor Hill's models and their original repository paths."""

    print(f"noble catalog version {CATALOG_VERSION}")

    print(
        "Models provided by Connor Hill's repository at "
        "https://github.com/Plasmath/noble-tools-revised\n"
    )
    for number, (ident, relative) in enumerate(catalog, 1):
        suffix = "  [fissary]" if ident in FISSARIES else ""
        print(f"{number:3d}  {ident:<10}  {relative}{suffix}")


def list_history(catalog):
    """List historical names, duals, and discoverers in color."""

    print(f"noble catalog version {CATALOG_VERSION}")

    print(
        "See https://polytope.miraheze.org/wiki/List_of_noble_polyhedra "
        "for more information.\n"
    )

    missing = [
        ident
        for ident, _ in catalog
        if ident not in HISTORY
    ]

    if missing:
        sys.exit(
            "noble: missing historical data for: "
            + ", ".join(missing)
        )

    name_width = max(
        len(HISTORY[ident][0])
        for ident, _ in catalog
    )
    dual_width = max(
        len(HISTORY[ident][1])
        for ident, _ in catalog
    )
    symbol_width = max(
        len("Symbol"),
        max(len(ident) for ident, _ in catalog),
    )

    header = (
        f"{'No.':>3}  "
        f"{'Symbol':<{symbol_width}}  "
        f"{'Full name':<{name_width}}  "
        f"{'Dual':<{dual_width}}  "
        "Discoverer / Year"
    )

    print(header)
    print("-" * len(header))

    for number, (ident, _) in enumerate(catalog, 1):
        full_name, dual_name, discoverer, year = HISTORY[ident]

        if year:
            credit = f"{discoverer}, {year}"
        else:
            credit = discoverer

        line = (
            f"{number:3d}  "
            f"{ident:<{symbol_width}}  "
            f"{full_name:<{name_width}}  "
            f"{dual_name:<{dual_width}}  "
            f"{credit}"
        )

        color_number = DISCOVERER_COLORS.get(discoverer)

        if color_number is None:
            print(line)
        else:
            print(f"\033[38;5;{color_number}m{line}{RESET}")


def find_model(catalog, key):
    """Find a model by catalog number or Hill identifier."""

    if key.isdigit():
        number = int(key)

        if 1 <= number <= len(catalog):
            return catalog[number - 1]

        sys.exit(
            f"noble: model number must be between 1 and {len(catalog)}"
        )

    if key.lower().endswith(".off"):
        key = key[:-4]

    matches = [
        (ident, path)
        for ident, path in catalog
        if ident == key
    ]

    if not matches:
        sys.exit(f"noble: model not found: {key}")

    if len(matches) > 1:
        sys.exit(f"noble: ambiguous model name: {key}")

    return matches[0]


def output_off(ident, output=None, save=False):
    """Decompress the selected OFF model without changing its original bytes."""
    relative, digest, encoded = EMBEDDED_OFF[ident]
    try:
        data = zlib.decompress(base64.b85decode(encoded))
    except (ValueError, zlib.error) as exc:
        sys.exit(f"noble: corrupted embedded OFF data for {ident}: {exc}")
    if hashlib.sha256(data).hexdigest() != digest:
        sys.exit(f"noble: embedded checksum mismatch for {ident}")

    if save:
        destination = Path.cwd() / Path(relative).name
    elif output:
        destination = Path(output)
    else:
        destination = None

    if destination is None:
        sys.stdout.buffer.write(data)
    else:
        try:
            destination.write_bytes(data)
        except OSError as exc:
            sys.exit(f"noble: cannot write {destination}: {exc}")


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Retrieve Connor Hill's noble polyhedra and output them "
            "as OFF on stdout.\n\n"
            "OFF library embedded in this script."
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    parser.add_argument(
        "model",
        nargs="?",
        help="catalog number or Hill identifier, e.g. 42 or gD-19.1",
    )

    list_group = parser.add_mutually_exclusive_group()

    list_group.add_argument(
        "-l",
        "--list",
        action="store_true",
        help="list the noble polyhedra catalog",
    )

    list_group.add_argument(
        "-L",
        "--long-list",
        action="store_true",
        help="list historical names, duals, discoverers, and years",
    )

    output_group = parser.add_mutually_exclusive_group()

    output_group.add_argument(
        "-o",
        "--output",
        metavar="FILE",
        help="write OFF output to FILE instead of stdout",
    )

    output_group.add_argument(
        "-s",
        "--save",
        action="store_true",
        help="write OFF output using Hill's original filename in the current directory",
    )

    add_version_argument(parser)
    args = parser.parse_args()

    catalog = build_catalog()

    if args.list:
        list_catalog(catalog)
        return

    if args.long_list:
        list_history(catalog)
        return

    if args.model is None:
        parser.print_help()
        return

    ident, _ = find_model(catalog, args.model)

    output_off(
        ident,
        output=args.output,
        save=args.save,
    )


if __name__ == "__main__":
    main()
